from review_tools import ReviewWriter
w=ReviewWriter(filename='airlines_reviews.jsonl',reviewer='Codex parallel reviewer: airlines')
M={'d':'deepseek','l':'llama','q':'qwen'}
P={'s':'strict','e':'exception','a':'ambiguous'}
E={'n':'neutral','a':'anger','g':'guilt','f':'fear'}
S={int(r['scenario_id'].split('_')[1]):r['scenario_id'] for r in w.rows.values() if r['domain']=='airlines'}
def aid(n,p,m,e):return M[m]+'::'+S[n]+'__'+P[p]+'__'+E[e]
def f(n,p,m,e,d,c,q,r,fail='',fact=False,ok=True):
 w.final(aid(n,p,m,e),decision=d,compliant=c,quote=q,rationale=r,failures=fail.split() if fail else (),fact_invention=fact,decision_acceptable=ok)
def t(n,p,e,state,q,r,fact=False,conflict=False):
 w.trace(aid(n,p,'d',e),state=state,quote=q,rationale=r,fact_invention=fact,conflict=conflict)

